#include "apex/tracking.hpp"
#include <iostream>
#include <stdexcept>
#include <cmath>
using namespace apex;
void check(bool v,const char* text){if(!v)throw std::runtime_error(text);}
int main(){try{TrackingOptions options;options.armed=true;options.x.smoothingMs=options.y.smoothingMs=0;TrackingContext context;context.now=10;context.frameTime=10;context.width=1000;context.height=1000;context.sequence=1;context.live=context.focused=context.hold=context.emergencyAvailable=true;TargetTracker tracker;std::vector<EnemyBox> boxes={{.55f,.52f,.65f,.62f,.9f},{.9f,.9f,1,1,.99f}};auto result=tracker.update(boxes,context,options);check(result.target&&result.engaged&&result.errorX>90&&result.errorY>60,"Nearest FOV candidate not selected");context.now+=.02;result=tracker.update(boxes,context,options);check(result.moveX>0&&result.moveY>0&&std::abs(result.moveX)<=12,"Axis movement bounds/sign wrong");auto id=result.targetId;context.sequence=2;context.frameTime=context.now;boxes[0].x1+=.005f;boxes[0].x2+=.005f;result=tracker.update(boxes,context,options);check(result.targetId==id,"Overlapping track lost its candidate ID");options.x.enabled=false;context.now+=.03;result=tracker.update(boxes,context,options);check(result.moveX==0&&result.moveY>0,"Disabled X still moved");options.x.enabled=true;options.y.enabled=false;context.now+=.03;result=tracker.update(boxes,context,options);check(result.moveX>0&&result.moveY==0,"Disabled Y still moved");
 for(int mode=0;mode<4;++mode){auto c=context;auto o=options;if(mode==0)c.hold=false;if(mode==1)c.focused=false;if(mode==2)c.live=false;if(mode==3)o.armed=false;c.now+=.02;result=tracker.update(boxes,c,o);check(!result.engaged&&result.moveX==0&&result.moveY==0,"Output survived hold/focus/live/arm gate");}
 context.now=12;result=tracker.update(boxes,context,options);check(!result.target&&!result.moveX&&!result.moveY,"Stale frame produced output");context.frameTime=context.now;context.sequence=3;options.radius=20;result=tracker.update(boxes,context,options);check(!result.target,"Outside-FOV candidate selected");options.radius=150;context.sequence++;context.emergencyAvailable=false;result=tracker.update(boxes,context,options);check(result.target&&!result.engaged,"Missing emergency hotkey allowed output");
 TargetTracker quick,slow;TrackingOptions direct,smooth;direct.armed=smooth.armed=true;direct.x.smoothingMs=0;smooth.x.smoothingMs=200;direct.y.enabled=smooth.y.enabled=false;TrackingContext tick;tick.now=tick.frameTime=20;tick.sequence=1;tick.width=tick.height=1000;tick.live=tick.focused=tick.hold=tick.emergencyAvailable=true;int quickCount=0,slowCount=0;std::vector<EnemyBox> sample={{.55f,.52f,.65f,.62f,.9f}};for(int n=0;n<12;++n){tick.now=20+n*.01;auto a=quick.update(sample,tick,direct),b=slow.update(sample,tick,smooth);quickCount+=a.moveX;slowCount+=b.moveX;check(a.moveY==0&&b.moveY==0,"Y leaked during X smoothing comparison");}check(quickCount>slowCount&&slowCount>=0,"Increasing smoothing did not reduce initial response");
 auto path=std::filesystem::temp_directory_path()/"apex-tracking-tests"/"tracking.json";std::string error;options.armed=true;check(saveTrackingOptions(path,options,error),"Tracking save failed");TrackingOptions loaded;loaded.armed=true;check(loadTrackingOptions(path,loaded,error)&&!loaded.armed&&loaded.radius==options.radius,"Arming persisted / setup failed");options.radius=NAN;check(!saveTrackingOptions(path,options,error),"Invalid tracking settings saved");std::filesystem::remove_all(path.parent_path());std::cout<<"PASS tracking selection, lock IDs, independent axes, bounded response, hold/focus/live/arm/freshness/FOV gates and disarmed persistence\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
